create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade);
create table if not exists public.products(id bigint generated always as identity primary key,name text not null,category text not null,description text default '',price numeric(10,2) not null,mrp numeric(10,2),stock int not null default 0,status text not null default 'Draft',featured boolean not null default false,image_url text,created_at timestamptz not null default now());
create table if not exists public.offers(id bigint generated always as identity primary key,title text not null,description text default '',discount_type text,discount_value numeric(10,2),starts_at timestamptz,ends_at timestamptz,active boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),auth_user_id uuid unique references auth.users(id),name text,phone text,email text,created_at timestamptz not null default now());
create table if not exists public.orders(id bigint generated always as identity primary key,order_no text unique not null,customer_id uuid references public.customers(id),total numeric(10,2) not null,status text not null default 'New',address jsonb,created_at timestamptz not null default now());
create table if not exists public.order_items(id bigint generated always as identity primary key,order_id bigint references public.orders(id) on delete cascade,product_id bigint references public.products(id),product_name text not null,quantity int not null,unit_price numeric(10,2) not null);
alter table public.admin_users enable row level security;alter table public.products enable row level security;alter table public.offers enable row level security;alter table public.customers enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;
revoke all on public.admin_users,public.products,public.offers,public.customers,public.orders,public.order_items from anon,authenticated;
grant select on public.products,public.offers to anon,authenticated;grant select,insert,update,delete on public.products,public.offers,public.customers,public.orders,public.order_items to authenticated;grant select on public.admin_users to authenticated;
create policy "public reads published products" on public.products for select to anon,authenticated using(status='Published');
create policy "public reads active offers" on public.offers for select to anon,authenticated using(active=true);
create policy "admin sees own role" on public.admin_users for select to authenticated using(user_id=auth.uid());
create policy "admins manage products" on public.products for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=auth.uid())) with check(exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
create policy "admins manage offers" on public.offers for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=auth.uid())) with check(exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
create policy "admins manage customers" on public.customers for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=auth.uid())) with check(exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
create policy "admins manage orders" on public.orders for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=auth.uid())) with check(exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
create policy "admins manage order items" on public.order_items for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=auth.uid())) with check(exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
insert into public.products(name,category,description,price,mrp,stock,status,featured) values('Vitamin C Glow Serum','Skincare','Brightening daily serum',699,899,24,'Published',true),('Velvet Matte Lipstick','Makeup','Comfortable matte colour',499,599,8,'Published',true),('Nourishing Hair Serum','Hair Care','Lightweight finishing serum',549,699,15,'Published',false) on conflict do nothing;
